const contains=(p,t)=>{const x=new Date(t).getTime();return x>=new Date(p.start).getTime()&&x<new Date(p.end).getTime()};
const eventH=e=>{try{return typeof eventHours==='function'?N(eventHours(e)):N(e?.hours)}catch(_){return N(e?.hours)}};
const reportPct=(m,p,c,k)=>{try{const s=suggestedPcts(m,p);return Math.max(0,Math.min(100,N(reportValue(c,k,s[k]))))}catch(_){return N(c?.reported?.[k])}};
const planPct=(m,p,k)=>{try{return N(currentPlanPcts(m,p)?.[k])}catch(_){return 0}};

function allFlat(m){const out=[];for(const p of periods(m)){const c=m.exec?.closures?.[p.id];for(const e of c?.flatEvents||[])out.push({...clone(e),day:Number(p.index)||0,hours:eventH(e)})}return out}
function netFlatHours(m,endAt){const events=allFlat(m),start=m.exec?.actualRelease;if(!start||!endAt)return events.reduce((s,e)=>s+N(e.hours),0);try{return N(intervalUnionHours(events,{start,end:endAt,expectedHours:Math.max(0,dayDiff(start,endAt)*24)}))}catch(_){return events.reduce((s,e)=>s+N(e.hours),0)}}
function loadEventTime(load,status){if(status==='loaded')return load.loadedAt||load.history?.find(h=>h.status==='Cargada')?.at||null;if(status==='positioned')return load.positionedAt||[...(load.history||[])].reverse().find(h=>h.status==='Posicionada')?.at||null;return null}
function loadStatus(load,at){const t=new Date(at).getTime(),pos=loadEventTime(load,'positioned'),loaded=loadEventTime(load,'loaded');if(pos&&new Date(pos).getTime()<=t)return'Positioned';if(loaded&&new Date(loaded).getTime()<=t)return'Loaded';return'Pending'}
function dayOf(m,t){if(!t)return null;const p=periods(m).find(x=>contains(x,t));return p?Number(p.index):null}

function loadRows(m,snapshotAt){return (m.exec?.loads||[]).map((x,i)=>{const loadedAt=loadEventTime(x,'loaded'),positionedAt=loadEventTime(x,'positioned'),plannedDay=N(x.plannedDay||x.day||1),loadedDay=dayOf(m,loadedAt),positionedDay=dayOf(m,positionedAt);return{id:x.id||`L${i+1}`,description:x.description||`Load ${i+1}`,scope:x.scope||'Rig',vehicle:x.vehicle||'',owner:x.owner||'',plannedDay,loadedAt,positionedAt,loadedDay,positionedDay,status:loadStatus(x,snapshotAt),deltaDays:positionedDay?positionedDay-plannedDay:null}})}
function dailyRows(m){const loads=loadRows(m,m.exec?.actualAcceptance||new Date().toISOString()),all=allFlat(m);return periods(m).slice().sort((a,b)=>a.index-b.index).map(p=>{const c=m.exec?.closures?.[p.id]||{},day=N(p.index),flat=all.filter(e=>N(e.day)===day).reduce((s,e)=>s+N(e.hours),0);return{day,start:p.start,end:p.end,closedAt:c.closedAt||null,rd:reportPct(m,p,c,'rd'),move:reportPct(m,p,c,'rm'),ru:reportPct(m,p,c,'ru'),planRd:planPct(m,p,'rd'),planMove:planPct(m,p,'rm'),planRu:planPct(m,p,'ru'),plannedLoads:loads.filter(x=>x.plannedDay===day).length,loaded:loads.filter(x=>x.loadedDay===day).length,positioned:loads.filter(x=>x.positionedDay===day).length,flatHours:flat,permits:N(c.permitsDay),risks:N(c.risksDay),soc:N(c.ocDay),opsStoragePath:c.opsStoragePath||null,next24:c.next24||''}})}
function flatBreakdown(m,key){const g={};for(const e of allFlat(m)){let k;if(key==='cause'){try{k=FLAT_TYPES.find(x=>x.id===e.type)?.label||e.type}catch(_){k=e.type}}else k=e[key];k=String(k||'Sin clasificar');g[k]=(g[k]||0)+N(e.hours)}return Object.entries(g).map(([name,hours])=>({name,hours})).sort((a,b)=>b.hours-a.hours)}
function scopeBreakdown(loads){const g={};for(const x of loads){const k=x.scope||'Rig';g[k]=g[k]||{total:0,loaded:0,positioned:0};g[k].total++;if(x.status!=='Pending')g[k].loaded++;if(x.status==='Positioned')g[k].positioned++}return Object.entries(g).map(([scope,v])=>({scope,...v}))}
function milestoneRows(m){const base=m.milestones||[],execMs=periods(m).slice().reverse().map(p=>m.exec?.closures?.[p.id]?.milestones||[]).find(a=>a?.length)||[];return base.map((x,i)=>{const e=execMs[i]||{};return{name:x.name||e.name||`Milestone ${i+1}`,baseline:x.base||'',projection:e.forecast||x.forecast||'',actual:e.actual||''}})}
function lastProgress(m){const ps=periods(m).slice().sort((a,b)=>b.index-a.index);for(const p of ps){const c=m.exec?.closures?.[p.id];if(c)return{day:p.index,rd:reportPct(m,p,c,'rd'),move:reportPct(m,p,c,'rm'),ru:reportPct(m,p,c,'ru'),plan:(typeof currentPlanPcts==='function'?currentPlanPcts(m,p):{rd:0,rm:0,ru:0})}}return{day:0,rd:0,move:0,ru:0,plan:{rd:0,rm:0,ru:0}}}
function build(m,mode='auto'){
  const finalMode=mode==='final'||(mode==='auto'&&m.status==='closed'),snapshotAt=finalMode?(m.exec?.actualAcceptance||m.exec?.moveClosedAt||new Date().toISOString()):new Date().toISOString(),release=m.exec?.actualRelease||null,acceptance=m.exec?.actualAcceptance||null,gross=release?Math.max(0,dayDiff(release,snapshotAt)):0,flatNet=netFlatHours(m,snapshotAt),net=Math.max(0,gross-flatNet/24),loads=loadRows(m,snapshotAt),daily=dailyRows(m),progress=lastProgress(m),safety=daily.reduce((a,x)=>({permits:a.permits+x.permits,risks:a.risks+x.risks,soc:a.soc+x.soc}),{permits:0,risks:0,soc:0});
  return{schemaVersion:1,reportMode:finalMode?'FINAL':'LIVE',snapshotAt,moveId:m.id,masterRevision:N(m.syncMeta?.revision),executionRevision:N(m.execSyncMeta?.revision),status:m.status,meta:{rig:m.meta?.rig||'',operator:m.meta?.operator||'',origin:m.meta?.origin||'',destination:m.meta?.destination||'',distanceKm:N(m.meta?.distanceKm),plannedDays:N(m.meta?.plannedDays),moveCompany:m.meta?.moveCompany||'',supportCompany:m.meta?.supportCompany||'',actualRelease:release,actualAcceptance:acceptance,closedAt:m.exec?.moveClosedAt||null},summary:{plannedDays:N(m.meta?.plannedDays),grossDays:gross,netDays:net,varianceDays:gross-N(m.meta?.plannedDays),flatNetHours:flatNet,totalLoads:loads.length,loadedLoads:loads.filter(x=>x.status!=='Pending').length,positionedLoads:loads.filter(x=>x.status==='Positioned').length,remainingLoads:loads.filter(x=>x.status!=='Positioned').length,scopeGrowth:(m.exec?.loads||[]).filter(x=>x.isUnplanned===true).length},progress,loads,loadScope:scopeBreakdown(loads),daily,flatTime:{events:allFlat(m),byDay:daily.map(x=>({day:x.day,hours:x.flatHours})),byCause:flatBreakdown(m,'cause'),byResponsibility:flatBreakdown(m,'responsibility'),byCompany:flatBreakdown(m,'company'),byTreatment:flatBreakdown(m,'commercial')},safety,milestones:milestoneRows(m),lessonsLearned:m.closeoutLessons||''};
}

async function createRecord(m,type,snapshot){const db=SB();if(!db)throw new Error('Supabase no disponible.');const {data,error}=await db.rpc('riggo_move_report_create',{p_move_id:m.id,p_report_type:type,p_snapshot_at:snapshot.snapshotAt,p_master_revision:snapshot.masterRevision,p_execution_revision:snapshot.executionRevision,p_snapshot_json:snapshot});if(error)throw error;if(!data?.ok)throw new Error(data?.message||'No fue posible registrar el reporte.');return data}
async function listReports(moveId){const db=SB();if(!db)return[];const {data,error}=await db.rpc('riggo_move_report_list',{p_move_id:moveId});if(error)throw error;return data||[]}
async function setStorage(reportId,path){const db=SB(),{data,error}=await db.rpc('riggo_move_report_set_storage',{p_report_id:reportId,p_storage_path:path});if(error)throw error;return data}
async function ensureFinalSnapshot(m){if(m.status!=='closed')throw new Error('La Move aún no está completada.');const snapshot=build(m,'final'),row=await createRecord(m,'final',snapshot);return{row,snapshot}}

function kpi(label,value,sub=''){return`<div class="mi-kpi"><span>${esc(label)}</span><b>${esc(value)}</b>${sub?`<small>${esc(sub)}</small>`:''}</div>`}
function bar(v,max=100,cls=''){return`<i class="mi-bar ${cls}"><b style="width:${Math.max(0,Math.min(100,N(v)/Math.max(1,N(max))*100))}%"></b></i>`}
function loadChart(s){const rows=s.daily,max=Math.max(1,...rows.flatMap(x=>[x.plannedLoads,x.loaded,x.positioned]));return`<div class="mi-chart"><div class="mi-chart-legend"><span class="plan">Planned</span><span class="loaded">Loaded</span><span class="pos">Positioned</span></div>${rows.map(x=>`<div class="mi-chart-row"><b>D${x.day}</b><div>${bar(x.plannedLoads,max,'plan')}${bar(x.loaded,max,'loaded')}${bar(x.positioned,max,'pos')}</div><small>${x.plannedLoads}/${x.loaded}/${x.positioned}</small></div>`).join('')}</div>`}
function overviewHtml(s){return`<div class="mi-kpis">${kpi('Plan',`${s.summary.plannedDays.toFixed(1)} d`)}${kpi(s.reportMode==='FINAL'?'Gross Actual':'Elapsed',`${s.summary.grossDays.toFixed(2)} d`)}${kpi('Net Productive',`${s.summary.netDays.toFixed(2)} d`)}${kpi('Flat Time',`${s.summary.flatNetHours.toFixed(1)} h`)}${kpi('Loads Positioned',`${s.summary.positionedLoads} / ${s.summary.totalLoads}`)}${kpi('Scope Growth',`+${s.summary.scopeGrowth}`)}</div><div class="mi-phases">${[['Rig Down',s.progress.rd,s.progress.plan.rd],['Move',s.progress.move,s.progress.plan.rm],['Rig Up',s.progress.ru,s.progress.plan.ru]].map(([n,a,p])=>`<div><div class="mi-phase-head"><b>${n}</b><span>Actual ${Math.round(a)}% · Plan ${Math.round(p)}%</span></div><div class="mi-track"><i style="width:${a}%"></i><em style="left:${p}%"></em></div></div>`).join('')}</div><div class="mi-grid2"><section><h3>Loads by Day</h3>${loadChart(s)}</section><section><h3>Operational Summary</h3><div class="mi-mini"><div><span>Permits</span><b>${s.safety.permits}</b></div><div><span>Risk Assessments</span><b>${s.safety.risks}</b></div><div><span>SOC Cards</span><b>${s.safety.soc}</b></div><div><span>Days Recorded</span><b>${s.daily.length}</b></div></div></section></div>`}
function loadsHtml(s){return`${loadChart(s)}<div class="mi-table-wrap"><table class="mi-table"><thead><tr><th>Load</th><th>Scope</th><th>Plan</th><th>Loaded</th><th>Positioned</th><th>Δ</th><th>Status</th></tr></thead><tbody>${s.loads.map(x=>`<tr><td><b>${esc(x.description)}</b></td><td>${esc(x.scope)}</td><td>D${x.plannedDay}</td><td>${x.loadedDay?`D${x.loadedDay}`:'—'}</td><td>${x.positionedDay?`D${x.positionedDay}`:'—'}</td><td>${x.deltaDays==null?'—':`${x.deltaDays>0?'+':''}${x.deltaDays}d`}</td><td>${esc(x.status)}</td></tr>`).join('')}</tbody></table></div>`}
function dailyHtml(s){return`<div class="mi-table-wrap"><table class="mi-table"><thead><tr><th>Day</th><th>RD</th><th>Move</th><th>RU</th><th>Loads P/L/Pos</th><th>Flat</th><th>HSE P/R/SOC</th><th>OPS</th></tr></thead><tbody>${s.daily.map(x=>`<tr><td><b>D${x.day}</b></td><td>${Math.round(x.rd)}%</td><td>${Math.round(x.move)}%</td><td>${Math.round(x.ru)}%</td><td>${x.plannedLoads}/${x.loaded}/${x.positioned}</td><td>${x.flatHours.toFixed(1)}h</td><td>${x.permits}/${x.risks}/${x.soc}</td><td>${x.opsStoragePath?`<button class="btn small" data-mi-ops="${esc(x.opsStoragePath)}">Open</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`}
function reportsShell(){return`<div id="miReportHistory" class="mi-report-history"><div class="mi-empty">Loading reports…</div></div>`}
function intelBody(s,tab){return tab==='loads'?loadsHtml(s):tab==='daily'?dailyHtml(s):tab==='reports'?reportsShell():overviewHtml(s)}
