  const s=build(m),final=s.reportMode==='FINAL',route=[s.meta.origin,s.meta.destination].filter(Boolean).join(' → ');sheetRoot.innerHTML=`<div class="sheet-backdrop"><div class="sheet wide mi-sheet"><div class="sheet-handle"></div><div class="mi-head"><div><span>${final?'FINAL MOVE INTELLIGENCE':'LIVE MOVE INTELLIGENCE'}</span><h2>${esc(s.meta.rig)} · ${esc(route)}</h2><small>${esc(s.meta.operator)} · Snapshot ${fmt(s.snapshotAt)} · Exec r${s.executionRevision}</small></div><button id="miClose" class="btn">Cerrar</button></div><div class="mi-tabs"><button data-mi-tab="overview" class="${tab==='overview'?'active':''}">Overview</button><button data-mi-tab="loads" class="${tab==='loads'?'active':''}">Loads</button><button data-mi-tab="daily" class="${tab==='daily'?'active':''}">Daily</button><button data-mi-tab="reports" class="${tab==='reports'?'active':''}">Reports</button></div><div id="miBody">${intelBody(s,tab)}</div><div class="sheet-footer"><button id="miGenerate" class="btn primary">${final?'Generate Final Report':'Generate Progress Report'}</button></div></div></div>`;
  E('miClose').onclick=closeSheet;document.querySelectorAll('[data-mi-tab]').forEach(b=>b.onclick=()=>openIntel(m,b.dataset.miTab));E('miGenerate').onclick=()=>generateReport(m,final?'final':'progress',E('miGenerate'));
  document.querySelectorAll('[data-mi-ops]').forEach(b=>b.onclick=()=>openStorage(b.dataset.miOps));if(tab==='reports')loadReportHistory(m.id);
