async function openStorage(path){const db=SB();if(!db||!path)return;const {data,error}=await db.storage.from('riggo-files').createSignedUrl(path,3600);if(error)throw error;W.open(data.signedUrl,'_blank','noopener')}
async function loadReportHistory(moveId){const host=E('miReportHistory');if(!host)return;try{const rows=await listReports(moveId);host.innerHTML=rows.length?rows.map(r=>`<div class="mi-report-row"><div><b>${r.report_type==='final'?'FINAL':'PROGRESS'}</b><span>${fmt(r.snapshot_at)} · Exec r${N(r.execution_revision)}</span></div><div>${r.storage_path?`<button class="btn small" data-mi-report-open="${esc(r.storage_path)}">Open PDF</button>`:'<span class="status warn">Snapshot only</span>'}</div></div>`).join(''):'<div class="mi-empty">No reports generated yet.</div>';host.querySelectorAll('[data-mi-report-open]').forEach(b=>b.onclick=()=>openStorage(b.dataset.miReportOpen))}catch(e){host.innerHTML=`<div class="mi-empty">${esc(e.message||e)}</div>`}}

function reportHtml(s){const final=s.reportMode==='FINAL',flat=s.flatTime.byCause.slice(0,8);return`<div class="mi-pdf"><section class="mi-pdf-page"><header><div><b>RIGGO · OPERATIONS EXCELLENCE</b><h1>${final?'FINAL MOVE REPORT':'MOVE PROGRESS REPORT'}</h1></div><div class="mi-pdf-tag">${final?'FINAL':'LIVE SNAPSHOT'}</div></header><div class="mi-pdf-route"><h2>${esc(s.meta.rig)} · ${esc(s.meta.origin)} → ${esc(s.meta.destination)}</h2><p>${esc(s.meta.operator)} · ${esc(s.meta.moveCompany)} · Snapshot ${fmt(s.snapshotAt)} · Execution Revision ${s.executionRevision}</p></div>${overviewHtml(s)}<div class="mi-pdf-note">Generated from RigGO server-truth snapshot. Report generation does not modify execution progress.</div></section><section class="mi-pdf-page"><header><div><b>MOVE INTELLIGENCE</b><h1>Loads & Daily Performance</h1></div></header><h3>Load Movement by Day</h3>${loadChart(s)}${dailyHtml(s)}<h3>Flat Time Drivers</h3><div class="mi-pdf-bars">${flat.map(x=>`<div><span>${esc(x.name)}</span>${bar(x.hours,Math.max(1,...flat.map(y=>y.hours)))}<b>${x.hours.toFixed(1)} h</b></div>`).join('')||'<p>No Flat Time registered.</p>'}</div>${final&&s.lessonsLearned?`<h3>Lessons Learned</h3><p class="mi-lessons">${esc(s.lessonsLearned)}</p>`:''}</section></div>`}
function loadScript(url,test){if(test())return Promise.resolve();return new Promise((res,rej)=>{const s=document.createElement('script');s.src=url;s.async=true;s.onload=()=>test()?res():rej(new Error('Library unavailable'));s.onerror=()=>rej(new Error('Could not load '+url));document.head.appendChild(s)})}
async function pdfDeps(){if(!W.html2canvas)await loadScript('https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js',()=>typeof W.html2canvas==='function');if(!W.jspdf?.jsPDF)await loadScript('https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js',()=>!!W.jspdf?.jsPDF)}
async function pdfBlob(s){await pdfDeps();const host=document.createElement('div');host.className='mi-pdf-host';host.innerHTML=reportHtml(s);document.body.appendChild(host);try{const pages=[...host.querySelectorAll('.mi-pdf-page')],pdf=new W.jspdf.jsPDF({orientation:'portrait',unit:'mm',format:'a4',compress:true});for(let i=0;i<pages.length;i++){if(i)pdf.addPage('a4','portrait');const canvas=await W.html2canvas(pages[i],{scale:1.3,useCORS:true,backgroundColor:'#fff',logging:false,width:pages[i].scrollWidth,height:pages[i].scrollHeight,windowWidth:1200});pdf.addImage(canvas.toDataURL('image/jpeg',.91),'JPEG',0,0,210,297,undefined,'FAST')}return pdf.output('blob')}finally{host.remove()}}
async function generateReport(m,type,button){const final=type==='final';if(button){button.disabled=true;button.textContent='Generating…'}try{if(final&&m.status!=='closed')throw new Error('Final report requires a completed Move.');const s=build(m,final?'final':'live'),row=await createRecord(m,type,s),blob=await pdfBlob(s),stamp=new Date(s.snapshotAt).toISOString().replace(/[-:TZ.]/g,'').slice(0,14),name=`${final?'Final_Move_Report':'Move_Progress_Report'}_${safe(s.meta.rig)}_${stamp}.pdf`,path=`${m.id}/move-reports/${row.id}/${name}`,db=SB(),up=await db.storage.from('riggo-files').upload(path,blob,{contentType:'application/pdf',upsert:true,cacheControl:'3600'});if(up.error)throw up.error;await setStorage(row.id,path);const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);try{toast(final?'Final Move Report generated ✓':'Progress Report generated ✓')}catch(_){};return{row,snapshot:s,path}}catch(e){alert('Could not generate Move report: '+String(e.message||e));throw e}finally{if(button){button.disabled=false;button.textContent=final?'Generate Final Report':'Generate Progress Report'}}}

function installHistoryAuthority(){const R=W.RigGOV97;if(!R||R.__mi122)return;const base=R.historyRows?.bind(R);R.historyRows=function(){let rows=[];try{rows=base?base():[]}catch(_){}const seen=new Set(rows.map(x=>String(x.id)));for(const m of state?.moves||[]){if(m.status!=='closed'||!m.exec?.actualRelease||!m.exec?.actualAcceptance||seen.has(String(m.id)))continue;try{const x=closeoutHistoryRow(m);rows.push({id:m.id,rig:x.rig,operator:x.operator,origin:m.meta.origin,destination:m.meta.destination,distance:x.distance,company:x.company,plan:N(x.plan),gross:N(x.gross),net:N(x.net),actualDays:periods(m).filter(p=>m.exec?.closures?.[p.id]?.closedAt).length,flatHours:N(x.flatNetHours),acceptance:m.exec.actualAcceptance,release:m.exec.actualRelease,type:m.management?.type||'Real',source:'RigGO',rm:m.access?.assignedEmails?.[0]||'',scopeGrowth:(m.exec?.loads||[]).filter(x=>x.isUnplanned===true).length,move:m})}catch(_){}}return rows};R.__mi122=true}
function performanceMoveId(el){if(!el)return'';return el.dataset.v106Live||el.dataset.v104Live||el.dataset.v97Live||el.dataset.v90Live||el.dataset.v71Live||el.dataset.v41Live||el.dataset.v97Hist||el.dataset.v90Hist||el.dataset.v71Hist||el.dataset.v4Intel||''}
