function bindPerformanceDom(){
  if(state?.screen!=='overall')return;
  const head=document.querySelector('.v106-head,.v104-head,.v90-head,.v71-head,.v41-command-head,.screen-title');
  if(head&&!head.querySelector('.mi122-live-badge')){const badge=document.createElement('span');badge.className='mi122-live-badge';badge.textContent='MOVE INTELLIGENCE 12.3';const target=head.querySelector('h1')?.parentElement||head;target.appendChild(badge)}
  const selectors='[data-v106-live],[data-v104-live],[data-v97-live],[data-v90-live],[data-v71-live],[data-v41-live],[data-v97-hist],[data-v90-hist],[data-v71-hist],[data-v4-intel]';
  document.querySelectorAll(selectors).forEach(el=>{
    const m=nativePerformanceMove(el);if(!m)return;
    el.dataset.mi122Bound='1';
    el.onclick=e=>{e?.preventDefault?.();e?.stopPropagation?.();openIntel(m)};
    if(el.matches('[data-v106-live],[data-v104-live],[data-v97-live],[data-v90-live],[data-v71-live],[data-v41-live]')&&!el.querySelector('.mi122-card-tag')){const tag=document.createElement('span');tag.className='mi122-card-tag';tag.textContent='Intelligence ›';el.appendChild(tag)}
  });
}
